namespace Hix.Functions;

public static class MetadataFunctions {
  public static void Register(FunctionSignatureRegistryBuilder definitions) {
    definitions.AddLibrary("""
      %description("Marks a declaration generated by the compiler.")
      runtime meta synthetic() for function type mixin field;
      %description("Allows the final function input to accept remaining arguments.")
      meta variadic() for field;
      %description("Allows a field to be absent without making null a valid value.")
      meta optional() for pattern field;
      %description("Adds descriptive documentation.")
      meta description(string text) for pattern field type function mixin;
      %description("Declares a scoped type parameter followed by optional pattern bounds.")
      meta generic(string name, %variadic pattern bounds) for function;
      meta requiresPrelude() for function;
      meta reference(string kind) for field;
      %description("Names a bytecode location, optionally preserving its decompiled type.")
      meta marker(string name) for statement variable;
      meta marker(string name, string type) for statement variable;
      %description("Matches repeated tuple elements.")
      meta many() for pattern field;
      meta many(pattern element) for pattern field;
      %description("Matches table keys and values.")
      meta map(string valueType) for pattern field;
      meta map(pattern key, pattern value) for pattern field;
      %description("Matches any supplied pattern.")
      meta union(pattern first, %variadic pattern rest) for pattern field;
      %description("Matches one constant value.")
      meta const(any value) for pattern field;
      %description("Restricts a pattern to constant values.")
      meta enum(any first, %variadic any rest) for pattern field;
      %description("Adds an inclusive or exclusive minimum constraint.")
      meta min(any value) for pattern field;
      meta min(any value, bool exclusive) for pattern field;
      %description("Adds an inclusive or exclusive maximum constraint.")
      meta max(any value) for pattern field;
      meta max(any value, bool exclusive) for pattern field;
      %description("Adds an exact-length constraint.")
      meta length(any value) for pattern field;
      %description("Adds a regular-expression constraint.")
      meta matches(string expression) for pattern field;
      %description("Adds a display title.")
      meta title(string text) for pattern field type function mixin;
      %description("Adds documentation. Prefer %description for new declarations.")
      meta doc(string text) for function mixin;
      %description("Sets a table-field default.")
      meta default(any value) for field;
      %description("Marks a field as a graph value input or an outgoing flow link.")
      meta graph(string kind) for field;
      %description("Adds a required $type discriminator, defaulting to the type name.")
      meta tagged() for type;
      meta tagged(string discriminator) for type;
      %description("Imports relative Hix path globs.")
      meta import(string path) for file;
      %description("Imports a namespace prefix for name resolution.")
      meta using(string prefix) for file;
      meta using(string prefix, string alias) for file;
      %description("Selects the analyzer backend.")
      meta backend(string name) for file;
      %description("Configures compiler diagnostics and artifacts.")
      meta pragma(string option) for file;
      %description("Configures virtual-machine diagnostics.")
      meta vm(string option) for file;
      """);
  }
}
